    private const FORMAT='sokna-component-package-v1';
    private const STATE_FORMAT='sokna-public-update-state-v1';
    private const MAX_FILES=12000;
    private const MAX_EXPANDED=536870912;
    private const STABLE_PREFIXES=['public/emergency.php','src/Emergency/','resources/update-trust-v1.json'];
    /** @var null|callable */ private $health;
    public function __construct(private readonly string $componentRoot,private readonly string $storageRoot,private readonly string $trustFile,?callable $health=null){$this->health=$health;}
    public function snapshot(): array{$s=$this->state();return ['current_version'=>$this->currentVersion(),'active_version'=>(string)($s['active_version']??$this->currentVersion()),'previous_version'=>(string)($s['previous_version']??''),'lkg_recovery_id'=>(string)($s['lkg_recovery_id']??''),'staged'=>$s['staged']??null,'history'=>array_slice(array_reverse((array)($s['history']??[])),0,30),'stable_entrypoint'=>'/emergency.php','signature_policy'=>(string)($this->trust()['signature_policy']??'unknown')];}
    public function stageUploadedZip(string $zipPath,string $actor='emergency'): array{$meta=$this->verifyZip($zipPath);$m=$meta['manifest'];$version=(string)$m['version'];$hash=hash_file('sha256',$zipPath);$target=$this->root().'/staged/'.$version;if(is_dir($target)){$x=$this->readJson($target.'/package.json');if(($x['package_sha256']??'')!==$hash)throw new PublicUpdateException('immutable_version_conflict','This version is already staged with different bytes.',409);}else{$tmp=$target.'.staging-'.bin2hex(random_bytes(4));$this->removeTree($tmp);$this->mkdir($tmp.'/payload');$this->extractPayload($zipPath,$tmp.'/payload',(array)$m['files']);copy($zipPath,$tmp.'/package.zip');$this->writeJson($tmp.'/manifest.json',$m);$this->writeJson($tmp.'/package.json',['package_sha256'=>$hash,'signature_status'=>$meta['signature_status'],'staged_at'=>gmdate('c')]);$this->verifyDirectory($tmp.'/payload',(array)$m['files']);if(!@rename($tmp,$target)){ $this->removeTree($tmp);throw new PublicUpdateException('stage_failed','Public stage failed.',500);}}$s=$this->state();$s['staged']=['version'=>$version,'package_sha256'=>$hash,'source_commit'=>(string)($m['source_commit']??''),'signature_status'=>$meta['signature_status'],'staged_at'=>gmdate('c')];$this->event($s,'stage',$version,$actor,['package_sha256'=>$hash]);$this->save($s);return $s['staged'];}
    public function activateStaged(string $actor='emergency'): array{$s=$this->state();$version=(string)(($s['staged']??[])['version']??'');if($version==='')throw new PublicUpdateException('nothing_staged','No Public package is staged.',409);if($version===$this->currentVersion())throw new PublicUpdateException('same_version_requires_repair','Use Repair for the active version.',409);$dir=$this->root().'/staged/'.$version;$m=$this->readJson($dir.'/manifest.json');$this->verifyDirectory($dir.'/payload',(array)($m['files']??[]));$recovery=$this->createRecoveryPoint('before_activate_'.$version,$actor);$old=$this->currentVersion();try{$this->deployPayload($dir.'/payload');$this->healthCheck();}catch(Throwable $e){$this->restoreRecoveryPoint((string)$recovery['id']);$this->event($s,'rollback_auto',$version,$actor,['error'=>'activation_health_failed']);$this->save($s);throw new PublicUpdateException('activation_failed','Public activation failed and was rolled back.',500);} $s=$this->state();$s['previous_version']=$old;$s['active_version']=$version;$s['lkg_recovery_id']=$recovery['id'];$s['staged']=null;$this->event($s,'activate',$version,$actor,['previous'=>$old,'recovery_id'=>$recovery['id']]);$this->save($s);return $this->snapshot();}
    public function repairStaged(string $actor='emergency'): array{$s=$this->state();$version=(string)(($s['staged']??[])['version']??'');if($version===''||$version!==$this->currentVersion())throw new PublicUpdateException('repair_requires_same_version','Repair requires a staged package matching the active version.',409);$dir=$this->root().'/staged/'.$version;$this->verifyDirectory($dir.'/payload',(array)$this->readJson($dir.'/manifest.json')['files']);$recovery=$this->createRecoveryPoint('before_repair_'.$version,$actor);try{$this->deployPayload($dir.'/payload');$this->healthCheck();}catch(Throwable){$this->restoreRecoveryPoint((string)$recovery['id']);throw new PublicUpdateException('repair_failed','Public repair failed and was rolled back.',500);} $s=$this->state();$s['staged']=null;$s['lkg_recovery_id']=$recovery['id'];$this->event($s,'repair',$version,$actor,['recovery_id'=>$recovery['id']]);$this->save($s);return $this->snapshot();}
    public function rollback(string $actor='emergency'): array{$s=$this->state();$id=(string)($s['lkg_recovery_id']??'');if($id==='')throw new PublicUpdateException('no_recovery_point','No LKG recovery point exists.',409);$from=$this->currentVersion();$m=$this->restoreRecoveryPoint($id);$to=(string)($m['version']??'unknown');$s=$this->state();$s['active_version']=$to;$s['previous_version']=$from;$this->event($s,'rollback',$to,$actor,['from'=>$from,'recovery_id'=>$id]);$this->save($s);return $this->snapshot();}
    public function incomingDir(): string{$p=$this->root().'/incoming';$this->mkdir($p);return $p;}
    public function currentVersion(): string{$s=$this->readJson($this->root().'/state.json');$v=trim((string)($s['active_version']??''));if($v!=='')return $v;$f=@file_get_contents($this->componentRoot.'/VERSION.txt');return is_string($f)&&trim($f)!==''?trim($f):'unknown';}
    private function verifyZip(string $path): array{if(!class_exists(ZipArchive::class))throw new PublicUpdateException('zip_unavailable','PHP ZipArchive is unavailable.',500);if(!is_file($path))throw new PublicUpdateException('package_missing','Update package is missing.',404);$z=new ZipArchive();if($z->open($path)!==true)throw new PublicUpdateException('invalid_zip','Invalid ZIP package.');try{$raw=$z->getFromName('manifest.json');if(!is_string($raw))throw new PublicUpdateException('manifest_missing','manifest.json is required.');$m=json_decode($raw,true,64,JSON_THROW_ON_ERROR);if(!is_array($m)||($m['format']??'')!==self::FORMAT||(int)($m['schema_version']??0)!==1||(string)($m['component']??'')!=='public-edge')throw new PublicUpdateException('manifest_contract','Public update manifest is invalid.');$version=trim((string)($m['version']??''));if(!preg_match('/^[0-9A-Za-z][0-9A-Za-z._+-]{0,63}$/',$version))throw new PublicUpdateException('invalid_version','Package version is invalid.');$files=(array)($m['files']??[]);if($files===[]||count($files)>self::MAX_FILES)throw new PublicUpdateException('invalid_file_count','Package file count is invalid.');$expected=[];$expanded=0;foreach($files as $e){$rel=$this->safeRelative((string)($e['path']??''));$this->assertNotStable($rel);$size=(int)($e['size']??-1);$hash=strtolower((string)($e['sha256']??''));if($size<0||!preg_match('/^[a-f0-9]{64}$/',$hash)||isset($expected[$rel]))throw new PublicUpdateException('manifest_contract','Package file record is invalid.');$expected[$rel]=[$size,$hash];$expanded+=$size;if($expanded>self::MAX_EXPANDED)throw new PublicUpdateException('package_too_large','Expanded package exceeds limit.',413);} $actual=[];for($i=0;$i<$z->numFiles;$i++){$n=(string)$z->getNameIndex($i);if($n==='manifest.json'||$n==='signature.json')continue;if(str_ends_with($n,'/'))continue;if(!str_starts_with($n,'payload/'))throw new PublicUpdateException('unexpected_entry','Unexpected ZIP entry.');$rel=$this->safeRelative(substr($n,8));if(isset($actual[$rel]))throw new PublicUpdateException('duplicate_entry','Duplicate ZIP path.');$actual[$rel]=true;if(!isset($expected[$rel]))throw new PublicUpdateException('unexpected_entry','ZIP entry is not declared.');[$size,$hash]=$expected[$rel];$stream=$z->getStream($n);if(!is_resource($stream))throw new PublicUpdateException('read_failed','ZIP entry could not be read.',500);$ctx=hash_init('sha256');$read=0;while(!feof($stream)){$buf=fread($stream,1048576);if($buf===false)break;$read+=strlen($buf);hash_update($ctx,$buf);}fclose($stream);if($read!==$size||!hash_equals($hash,hash_final($ctx)))throw new PublicUpdateException('hash_mismatch','Package file hash mismatch.');}if(count($actual)!==count($expected))throw new PublicUpdateException('payload_set_mismatch','Package payload set is incomplete.');$contracts=(array)($m['contracts']??[]);if((int)($contracts['local_public_contract']??0)!==1)throw new PublicUpdateException('incompatible_contract','Local/Public contract is incompatible.',409);return ['manifest'=>$m,'signature_status'=>$this->verifySignature($z,$raw)];}catch(PublicUpdateException $e){throw $e;}catch(Throwable){throw new PublicUpdateException('package_invalid','Public update package is invalid.');}finally{$z->close();}}
    private function verifySignature(ZipArchive $z,string $manifestRaw): string{$trust=$this->trust();$sigRaw=$z->getFromName('signature.json');$required=(string)($trust['signature_policy']??'')==='required';if(!is_string($sigRaw)){if($required)throw new PublicUpdateException('signature_required','Package signature is required.');return 'not_present_pre_release_allowed';}$sig=json_decode($sigRaw,true,16,JSON_THROW_ON_ERROR);$keyId=(string)($sig['key_id']??'');$keys=(array)($trust['ed25519_public_keys']??[]);$pub=base64_decode((string)($keys[$keyId]??''),true);$raw=base64_decode((string)($sig['signature_base64']??''),true);if(($sig['algorithm']??'')!=='ed25519'||!is_string($pub)||strlen($pub)!==SODIUM_CRYPTO_SIGN_PUBLICKEYBYTES||!is_string($raw)||strlen($raw)!==SODIUM_CRYPTO_SIGN_BYTES||!sodium_crypto_sign_verify_detached($raw,$manifestRaw,$pub))throw new PublicUpdateException('bad_signature','Package signature is invalid.');return 'verified_ed25519';}
    private function extractPayload(string $zipPath,string $target,array $files): void{$z=new ZipArchive();$z->open($zipPath);try{foreach($files as $e){$rel=$this->safeRelative((string)$e['path']);$dst=$target.'/'.$rel;$this->mkdir(dirname($dst));$in=$z->getStream('payload/'.$rel);$out=fopen($dst,'wb');if(!is_resource($in)||!is_resource($out))throw new PublicUpdateException('extract_failed','Package extraction failed.',500);stream_copy_to_stream($in,$out);fclose($in);fclose($out);}}finally{$z->close();}}
    private function createRecoveryPoint(string $reason,string $actor): array{$id=gmdate('Ymd-His').'-'.bin2hex(random_bytes(4));$dir=$this->root().'/recovery-points/'.$id;$this->copyMutableTree($this->componentRoot,$dir.'/payload');$files=$this->hashTree($dir.'/payload');$m=['format'=>'sokna-public-recovery-point-v1','id'=>$id,'version'=>$this->currentVersion(),'created_at'=>gmdate('c'),'reason'=>$reason,'actor_hint'=>$actor,'files'=>$files];$this->writeJson($dir.'/manifest.json',$m);return $m;}
    private function restoreRecoveryPoint(string $id): array{if(!preg_match('/^[0-9]{8}-[0-9]{6}-[a-f0-9]{8}$/',$id))throw new PublicUpdateException('invalid_recovery_id','Recovery id is invalid.');$dir=$this->root().'/recovery-points/'.$id;$m=$this->readJson($dir.'/manifest.json');if(($m['format']??'')!=='sokna-public-recovery-point-v1')throw new PublicUpdateException('recovery_missing','Recovery point is invalid.',404);$this->verifyDirectory($dir.'/payload',(array)$m['files']);$this->deployPayload($dir.'/payload');$this->healthCheck();return $m;}
    private function deployPayload(string $source): void{$this->removeMutableFiles($this->componentRoot);$this->copyTree($source,$this->componentRoot,false);}
    private function healthCheck(): void{foreach(['bootstrap.php','public/index.php','public/emergency.php'] as $rel)if(!is_file($this->componentRoot.'/'.$rel))throw new PublicUpdateException('health_failed','Critical Public file is missing.',500,['file'=>$rel]);if(is_callable($this->health)){$ok=(bool)($this->health)();if(!$ok)throw new PublicUpdateException('health_failed','Public health callback failed.',500);} }
    private function copyMutableTree(string $src,string $dst): void{$this->removeTree($dst);$this->mkdir($dst);$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($src,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::SELF_FIRST);foreach($it as $f){$rel=str_replace('\\','/',substr($f->getPathname(),strlen($src)+1));if($this->stable($rel)||$this->runtimeExcluded($rel))continue;$to=$dst.'/'.$rel;if($f->isDir())$this->mkdir($to);elseif($f->isFile()){ $this->mkdir(dirname($to));if(!copy($f->getPathname(),$to))throw new PublicUpdateException('copy_failed','Recovery copy failed.',500);}}}
    private function removeMutableFiles(string $root): void{$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){$rel=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if($this->stable($rel)||$this->runtimeExcluded($rel))continue;if($f->isFile()||$f->isLink())@unlink($f->getPathname());elseif($f->isDir())@rmdir($f->getPathname());}}
    private function runtimeExcluded(string $rel): bool{return $rel==='config.php'||str_starts_with($rel,'storage/');}
    private function stable(string $rel): bool{foreach(self::STABLE_PREFIXES as $p)if($rel===$p||str_ends_with($p,'/')&&str_starts_with($rel,$p))return true;return false;}
    private function assertNotStable(string $rel): void{if($this->stable($rel)||$this->runtimeExcluded($rel))throw new PublicUpdateException('stable_path_forbidden','Update package may not replace stable emergency/config/storage paths.',422,['path'=>$rel]);}
    private function verifyDirectory(string $root,array $files): void{$expected=[];foreach($files as $e){$rel=$this->safeRelative((string)$e['path']);$expected[$rel]=true;$p=$root.'/'.$rel;if(!is_file($p)||(int)filesize($p)!==(int)$e['size']||!hash_equals(strtolower((string)$e['sha256']),strtolower((string)hash_file('sha256',$p))))throw new PublicUpdateException('staged_integrity_failed','Staged file integrity failed.',422,['file'=>$rel]);}$actual=[];if(is_dir($root)){$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS));foreach($it as $f)if($f->isFile())$actual[str_replace('\\','/',substr($f->getPathname(),strlen($root)+1))]=true;}if(count($actual)!==count($expected)||array_diff_key($actual,$expected)||array_diff_key($expected,$actual))throw new PublicUpdateException('payload_set_mismatch','Staged file set changed.',422);}
    private function hashTree(string $root): array{$out=[];if(!is_dir($root))return $out;$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS));foreach($it as $f)if($f->isFile()){$rel=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));$out[]=['path'=>$rel,'size'=>$f->getSize(),'sha256'=>hash_file('sha256',$f->getPathname())];}usort($out,fn($a,$b)=>strcmp($a['path'],$b['path']));return $out;}
    private function copyTree(string $src,string $dst,bool $clear=true): void{if($clear)$this->removeTree($dst);$this->mkdir($dst);$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($src,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::SELF_FIRST);foreach($it as $f){$rel=substr($f->getPathname(),strlen($src)+1);$to=$dst.'/'.$rel;if($f->isDir())$this->mkdir($to);elseif($f->isFile()){ $this->mkdir(dirname($to));if(!copy($f->getPathname(),$to))throw new PublicUpdateException('copy_failed','Lifecycle copy failed.',500);}}}
    private function removeTree(string $p): void{if(!file_exists($p))return;if(is_file($p)||is_link($p)){@unlink($p);return;}$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($p,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){$f->isDir()?@rmdir($f->getPathname()):@unlink($f->getPathname());}@rmdir($p);}
    private function state(): array{$s=$this->readJson($this->root().'/state.json');if(($s['format']??'')!==self::STATE_FORMAT)$s=['format'=>self::STATE_FORMAT,'schema_version'=>1,'active_version'=>$this->currentVersion(),'previous_version'=>'','lkg_recovery_id'=>'','staged'=>null,'history'=>[]];return $s;}
    private function save(array $s): void{$this->writeJson($this->root().'/state.json',$s);}
    private function event(array &$s,string $action,string $version,string $actor,array $extra=[]): void{$s['history'][]=['at'=>gmdate('c'),'action'=>$action,'version'=>$version,'actor_hint'=>substr($actor,0,120),'result'=>'success']+$extra;$s['history']=array_slice($s['history'],-100);}
    private function root(): string{$p=rtrim($this->storageRoot,"\\/").'/emergency/update';$this->mkdir($p);return $p;}
    private function trust(): array{return $this->readJson($this->trustFile);}
    private function readJson(string $p): array{$raw=@file_get_contents($p);if(!is_string($raw)||$raw==='')return [];try{$v=json_decode($raw,true,64,JSON_THROW_ON_ERROR);return is_array($v)?$v:[];}catch(Throwable){return [];}}
    private function writeJson(string $p,array $v): void{$this->mkdir(dirname($p));$tmp=$p.'.tmp-'.bin2hex(random_bytes(4));if(file_put_contents($tmp,json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n",LOCK_EX)===false||!@rename($tmp,$p)){@unlink($tmp);throw new PublicUpdateException('state_write_failed','Lifecycle state write failed.',500);}@chmod($p,0600);}
    private function safeRelative(string $r): string{$r=str_replace('\\','/',trim($r));if($r===''||str_starts_with($r,'/')||preg_match('#(^|/)\.\.(/|$)#',$r)||str_contains($r,"\0"))throw new PublicUpdateException('unsafe_path','Unsafe package path.');return $r;}
    private function mkdir(string $p): void{if(!is_dir($p)&&!@mkdir($p,0700,true)&&!is_dir($p))throw new PublicUpdateException('storage_unavailable','Lifecycle storage is unavailable.',500);}
}
